const fs=require('fs'),path=require('path'),https=require('https'),http=require('http'),net=require('net');
const BASE=__dirname,ORIGIN='https://ops-cue-geekten-demo.vercel.app',HOST=new URL(ORIGIN).hostname,RUN=path.join(BASE,'public-browser-check-'+Date.now());fs.mkdirSync(RUN);fs.mkdirSync(path.join(RUN,'tmp'));process.env.TEMP=process.env.TMP=path.join(RUN,'tmp');
const {chromium}=require('C:/Users/user/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const result={run:RUN,preflight:[],requests:[],denied:[],errors:[],views:[],timings:[]};let fatal=null,ctx,proxy;const sockets=new Set(),allowed=new Set();
const save=(n,v)=>fs.writeFileSync(path.join(RUN,n),typeof v==='string'?v:JSON.stringify(v,null,2),{flag:'wx'});
function stop(v){result.denied.push(v);fatal=Error(JSON.stringify(v));}
function check(){if(fatal)throw fatal;}
function get(url){return new Promise((resolve,reject)=>{const u=new URL(url);if(u.origin!==ORIGIN)return reject(Error('External static ref'));https.get(url,{headers:{'Accept-Encoding':'identity'}},r=>{let b=[];r.on('data',x=>b.push(x));r.on('end',()=>{if(r.statusCode!==200||r.headers.location||r.headers['set-cookie'])return reject(Error('Unexpected static response '+url+' '+r.statusCode));resolve({text:Buffer.concat(b).toString(),type:r.headers['content-type']||''});});}).on('error',reject);});}
async function inspect(){const queue=['/'];const seen=new Set();while(queue.length){const p=queue.shift();if(seen.has(p))continue;seen.add(p);if(seen.size>120)throw Error('Crawl limit');const u=new URL(p,ORIGIN);if(u.origin!==ORIGIN||u.search)throw Error('Unverified reference '+p);if(!(/^\/(?:$|worker\/|admin\/|guide\/|_next\/static\/)/.test(u.pathname)))continue;const r=await get(u.href);allowed.add(u.pathname);result.preflight.push({path:u.pathname,type:r.type});if(r.type.includes('text/html')){for(const m of r.text.matchAll(/(?:href|src)="([^"]+)"/g)){let t=m[1];if(t.startsWith('#')||t.startsWith('data:'))continue;const v=new URL(t,u);if(v.origin!==ORIGIN)throw Error('External reference '+v.href);v.hash='';if(v.pathname.startsWith('/_next/static/')||v.pathname==='/'||/^\/(worker|admin|guide)\//.test(v.pathname))queue.push(v.pathname);}}if(r.type.includes('css'))for(const m of r.text.matchAll(/url\(([^)]+)\)/g)){const v=new URL(m[1].replace(/["']/g,''),u);if(v.protocol==='data:')continue;if(v.origin!==ORIGIN)throw Error('External CSS reference');queue.push(v.pathname);}}save('static-allowlist.json',result.preflight);}
async function launch(role,w,h){ctx=await chromium.launchPersistentContext(path.join(RUN,'profile-'+role),{executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,viewport:{width:w,height:h},deviceScaleFactor:1,serviceWorkers:'block',acceptDownloads:false,permissions:[],proxy:{server:'http://127.0.0.1:'+proxy.address().port},args:['--disable-background-networking','--disable-component-update','--disable-sync','--disable-breakpad','--disable-crash-reporter','--no-first-run','--disable-quic']});
 await ctx.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());const entry={role,url:req.url(),method:req.method(),type:req.resourceType()};result.requests.push(entry);if(fatal||u.origin!==ORIGIN||u.search||!allowed.has(u.pathname)||!['GET','HEAD'].includes(req.method())||['websocket','eventsource'].includes(req.resourceType())){stop(entry);return route.abort();}try{const response=await route.fetch({maxRedirects:0});const headers=response.headers();entry.status=response.status();if(response.status()>=300&&response.status()<400||headers.location||headers['set-cookie']){stop({...entry,reason:'redirect/cookie'});return route.abort();}await route.fulfill({response});}catch(e){result.errors.push(String(e));await route.abort();}});
 await ctx.addInitScript(()=>{const fail=n=>{console.error('FORBIDDEN:'+n);throw Error(n)};if(navigator.serviceWorker)navigator.serviceWorker.register=()=>fail('ServiceWorker');if(window.Notification)Notification.requestPermission=()=>fail('Notification');window.WebSocket=class{constructor(){fail('WebSocket')}};window.EventSource=class{constructor(){fail('EventSource')}};});const page=ctx.pages()[0];page.on('console',m=>{if(m.text().startsWith('FORBIDDEN:'))stop({console:m.text()});});page.on('pageerror',e=>result.errors.push(String(e)));return page;}
async function view(page,name){check();const text=await page.locator('body').innerText();save(name+'.txt',text);await page.screenshot({path:path.join(RUN,name+'.png')});result.views.push({name,url:page.url(),viewport:page.viewportSize(),overflow:await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth}))});}
async function click(page,loc,label){check();const t=Date.now();await loc.click();await page.waitForLoadState('networkidle');check();result.timings.push({label,ms:Date.now()-t});}
(async()=>{try{await inspect();proxy=http.createServer((req,res)=>{stop({proxy:req.url});res.writeHead(403);res.end();});proxy.on('connect',(req,client,head)=>{if(req.url!==HOST+':443'){stop({proxyConnect:req.url});client.end('HTTP/1.1 403 Forbidden\r\n\r\n');return;}const upstream=net.connect(443,HOST,()=>{client.write('HTTP/1.1 200 Connection Established\r\n\r\n');if(head.length)upstream.write(head);upstream.pipe(client);client.pipe(upstream);});sockets.add(client);sockets.add(upstream);upstream.on('error',()=>client.destroy());client.on('error',()=>upstream.destroy());});await new Promise(r=>proxy.listen(0,'127.0.0.1',r));
 let p=await launch('worker',393,852);await p.goto(ORIGIN+'/worker/',{waitUntil:'networkidle'});await view(p,'worker-home');await click(p,p.getByRole('link',{name:'勤務詳細を見る',exact:true}),'worker-detail');await view(p,'worker-detail');await p.getByText('前日確認',{exact:true}).first().evaluate(el=>window.scrollTo({top:scrollY+el.getBoundingClientRect().top-130}));await view(p,'worker-confirmation');await ctx.close();ctx=null;
 p=await launch('admin',1280,832);await p.goto(ORIGIN+'/admin/',{waitUntil:'networkidle'});await view(p,'admin-home');await click(p,p.getByRole('link',{name:/案件一覧へ/}),'projects');await view(p,'admin-projects');await click(p,p.locator('a[href="/admin/projects/demo-exhibition/"]').first(),'project-detail');await view(p,'admin-project-detail');const links=await p.locator('a').evaluateAll(es=>es.map(e=>({text:e.innerText,href:e.getAttribute('href')})));save('project-detail-links.json',links);await click(p,p.locator('a[href="/admin/shifts/demo-reception/"]').first(),'shift-detail');await view(p,'admin-shift-detail');result.status='BROWSER_CHECK_COMPLETED';
}catch(e){result.status='STOPPED';result.failure=String(e.stack||e);}finally{if(ctx)await ctx.close().catch(e=>result.errors.push(String(e)));for(const s of sockets)s.destroy();if(proxy)await new Promise(r=>proxy.close(r));result.closed=true;save('result.json',result);console.log(JSON.stringify(result));}})();